 $expected=[[0,1,2,3],[1,0,3,2],[3,2,1,0],[2,3,0,1],[0,2,1,3],[2,0,3,1],[3,1,2,0],[1,3,0,2]];$colors=[[220,30,40],[20,180,70],[30,70,220],[225,180,20]];
