 $sparse=$root.'/above-source-budget.png';$h=fopen($sparse,'xb');ftruncate($h,\Kulturhus\Native\Cms\CameraPhotos::INPUT_BYTES+1);fclose($h);try{$check($run('above-source-budget.png')['status']==='rejected','source above256MiB rejects before decoding');}finally{unlink($sparse);}
 $fake=$root.'/own-sleep-node';file_put_contents($fake,"#!/bin/sh\nexec sleep 90\n");chmod($fake,0700);$env['VEREIN_PHOTO_NODE']=$fake;$started=hrtime(true);$r=$run('48mp.jpg',[],$env);$seconds=(hrtime(true)-$started)/1e9;$check($r['status']==='rejected'&&$r['message']==='Fotoverarbeitung dauerte zu lange.'&&$seconds>=45&&$seconds<55&&glob($temp.'/dvm-raster-*')===[],'actual45s watchdog kills and reaps its own decoder with complete cleanup');unlink($fake);
 $report=\Kulturhus\Native\Cms\PhotoRuntime::inspect();$check($report['present']&&$report['verified']===false,'readonly prerequisites remain explicitly unverified even with all local files present');
