 $process=proc_open([...\Kulturhus\Native\TestSupport::phpCommand(),'-d','open_basedir='.dirname(__DIR__,2).PATH_SEPARATOR.$temp,'-d','sys_temp_dir='.$temp,'-r',$probe],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$statusPipes,null,$statusEnvironment);if(!is_resource($process))throw new RuntimeException('Own restricted runtime probe unavailable');fclose($statusPipes[0]);$statusText=stream_get_contents($statusPipes[1]);$statusError=stream_get_contents($statusPipes[2]);fclose($statusPipes[1]);fclose($statusPipes[2]);if(proc_close($process)!==0)throw new RuntimeException('Restricted Node probe failed: '.$statusError);$restricted=json_decode($statusText,true,8,JSON_THROW_ON_ERROR);$check($restricted['stat']===false&&$restricted['node']===true&&$restricted['verified']===false,'actual Node version call remains available when PHP open_basedir blocks stat on the provider runtime, without certifying a decoder run');
